CREATE TRIGGER IF NOT EXISTS order_stock_confirm BEFORE UPDATE OF status ON orders WHEN OLD.status='pending' AND NEW.status='confirmed' BEGIN SELECT CASE WHEN EXISTS(SELECT 1 FROM json_each(OLD.items_json) j LEFT JOIN products p ON p.id=json_extract(j.value,'$.id') AND p.store_id=OLD.store_id WHERE p.id IS NULL OR p.stock<json_extract(j.value,'$.quantity')) THEN RAISE(ABORT,'Estoque insuficiente ou pedido antigo') END; UPDATE products SET stock=stock-(SELECT SUM(json_extract(j.value,'$.quantity')) FROM json_each(OLD.items_json) j WHERE json_extract(j.value,'$.id')=products.id) WHERE store_id=OLD.store_id AND id IN (SELECT json_extract(value,'$.id') FROM json_each(OLD.items_json)); END;
CREATE TRIGGER IF NOT EXISTS order_stock_cancel AFTER UPDATE OF status ON orders WHEN OLD.status='confirmed' AND NEW.status='cancelled' BEGIN UPDATE products SET stock=stock+(SELECT SUM(json_extract(j.value,'$.quantity')) FROM json_each(OLD.items_json) j WHERE json_extract(j.value,'$.id')=products.id) WHERE store_id=OLD.store_id AND id IN (SELECT json_extract(value,'$.id') FROM json_each(OLD.items_json)); END;
CREATE TRIGGER IF NOT EXISTS order_status_guard BEFORE UPDATE OF status ON orders WHEN OLD.status<>NEW.status AND NOT ((OLD.status='pending' AND NEW.status IN ('confirmed','cancelled')) OR (OLD.status='confirmed' AND NEW.status IN ('completed','cancelled'))) BEGIN SELECT RAISE(ABORT,'Transição inválida'); END;